/**
 * Filters combine with AND. `month` is mutually exclusive with
 * `from`/`to` (inclusive `from`, exclusive `to`). `q` is a literal,
 * case-insensitive substring over merchant text and notes (`%`, `_` and
 * regex characters have no special meaning). Order is posted date
 * descending, then ID descending. `totals` always cover every matching
 * row, computed in the same read snapshot as the page; financial totals
 * exclude voided rows even when `lifecycle` shows them.
 * @summary Search and filter transactions (keyset paginated)
 */
export const listTransactionsQueryLifecycleDefault = `active`;
export const listTransactionsQueryMonthRegExp = new RegExp('^(19|2[0-9])[0-9]{2}-(0[1-9]|1[0-2])$');
export const listTransactionsQueryFromRegExp = new RegExp('^(19|2[0-9])[0-9]{2}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$');
export const listTransactionsQueryToRegExp = new RegExp('^(19|2[0-9])[0-9]{2}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$');
export const listTransactionsQueryQMax = 200;

export const listTransactionsQueryCursorRegExp = new RegExp('^[A-Za-z0-9_-]{1,512}$');
export const listTransactionsQueryLimitDefault = 50;
export const listTransactionsQueryLimitMax = 200;



export const ListTransactionsQueryParams = zod.object({
  "accountId": zod.coerce.string().uuid().optional(),
  "categoryId": zod.coerce.string().uuid().optional().describe('Use the Uncategorized category ID to list uncategorized rows.'),
  "kind": zod.enum(['purchase', 'refund', 'income', 'transfer']).optional(),
  "origin": zod.enum(['manual', 'rule', 'unassigned', 'system']).optional().describe('Assignment origin, e.g. `manual`.'),
  "lifecycle": zod.enum(['active', 'void', 'all']).default(listTransactionsQueryLifecycleDefault).describe('Defaults to `active`. Totals always exclude voided rows.'),
  "month": zod.coerce.string().regex(listTransactionsQueryMonthRegExp).optional().describe('Posted month. Mutually exclusive with `from`/`to` (400 otherwise).'),
  "from": zod.coerce.string().date().regex(listTransactionsQueryFromRegExp).optional().describe('Inclusive posted-date lower bound.'),
  "to": zod.coerce.string().date().regex(listTransactionsQueryToRegExp).optional().describe('Exclusive posted-date upper bound.'),
  "q": zod.coerce.string().min(1).max(listTransactionsQueryQMax).optional().describe('Literal case-insensitive substring of merchant text or note.'),
  "cursor": zod.coerce.string().regex(listTransactionsQueryCursorRegExp).optional().describe('Opaque `nextCursor` from the previous page, used with the same filters.'),
  "limit": zod.coerce.number().int().min(1).max(listTransactionsQueryLimitMax).default(listTransactionsQueryLimitDefault)
}).strict()

