/**
 * Read from the status file written by the backup account. Local success
 * never masks an independent-copy failure.
 * @summary Local and independent backup outcomes
 */
export const getBackupStatusResponseReadAtRegExp = new RegExp('^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$');
export const getBackupStatusResponseDestinationsItemLastSuccessAtOneRegExp = new RegExp('^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$');
export const getBackupStatusResponseDestinationsItemLastAttemptAtOneRegExp = new RegExp('^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?Z$');
export const getBackupStatusResponseDestinationsItemErrorCodeRegExp = new RegExp('^[a-z][a-z0-9_]{0,63}$');
export const getBackupStatusResponseDestinationsMax = 2;



export const GetBackupStatusResponse = zod.object({
  "statusFile": zod.enum(['readable', 'missing', 'unreadable']),
  "readAt": zod.string().datetime({"offset":true}).regex(getBackupStatusResponseReadAtRegExp).describe('UTC RFC 3339 event time.'),
  "destinations": zod.array(zod.object({
  "destination": zod.enum(['local', 'independent']).describe('`local` is the RAID5 repository; `independent` is the encrypted off-host copy.'),
  "state": zod.enum(['ok', 'stale', 'failed', 'never_run', 'unknown']),
  "lastSuccessAt": zod.union([zod.string().datetime({"offset":true}).regex(getBackupStatusResponseDestinationsItemLastSuccessAtOneRegExp).describe('UTC RFC 3339 event time.'),zod.null()]),
  "lastAttemptAt": zod.union([zod.string().datetime({"offset":true}).regex(getBackupStatusResponseDestinationsItemLastAttemptAtOneRegExp).describe('UTC RFC 3339 event time.'),zod.null()]),
  "errorCode": zod.string().regex(getBackupStatusResponseDestinationsItemErrorCodeRegExp).nullable()
}).strict()).max(getBackupStatusResponseDestinationsMax)
}).strict()


